class TaskQueue:
    def __init__(self, capacity=16):
        self.capacity = capacity
        self.items = []

    def push(self, task):
        if len(self.items) >= self.capacity:
            raise OverflowError("queue is full")
        self.items.append(task)

    def pop(self):
        if not self.items:
            return None
        return self.items.pop(0)

    def size(self):
        return len(self.items)

